for i in range(int(input())):
	(x, y, z) = input().split()
	(x, y, z) = (int(x), int(y), int(z))
	l = [[0 for i in range(z)] for j in range(x * y)]
	l1 = []
	for i in range(x * y):
		l1.append(list(map(int, input().split())))
	for i in range(x):
		for j in range(y):
			for k in range(z):
				if i == 0 and j == 0 and (k == 0):
					l[i * y + j][k] = l1[i * y + j][k]
				elif i == 0 and j == 0:
					l[i * y + j][k] = l1[i * y + j][k] - l1[i * y + j][k - 1]
				elif i == 0 and k == 0:
					l[i * y + j][k] = l1[i * y + j][k] - l1[i * y + (j - 1)][k]
				elif j == 0 and k == 0:
					l[i * y + j][k] = l1[i * y + j][k] - l1[(i - 1) * y + j][k]
				elif i == 0:
					l[i * y + j][k] = l1[i * y + j][k] - l1[i * y + (j - 1)][k] - l1[i * y + j][k - 1] + l1[i * y + (j - 1)][k - 1]
				elif j == 0:
					l[i * y + j][k] = l1[i * y + j][k] - l1[(i - 1) * y + j][k] - l1[i * y + j][k - 1] + l1[(i - 1) * y + j][k - 1]
				elif k == 0:
					l[i * y + j][k] = l1[i * y + j][k] - l1[(i - 1) * y + j][k] - l1[i * y + (j - 1)][k] + l1[(i - 1) * y + (j - 1)][k]
				else:
					l[i * y + j][k] = l1[i * y + j][k] - l1[(i - 1) * y + j][k] - l1[i * y + (j - 1)][k] - l1[i * y + j][k - 1] + l1[(i - 1) * y + (j - 1)][k] + l1[(i - 1) * y + j][k - 1] + l1[i * y + (j - 1)][k - 1] - l1[(i - 1) * y + (j - 1)][k - 1]
	for i in l:
		for j in i:
			print(j, '', end='')
		print()
